action.code:
# Let's manually examine the differences
inputs = ['jxv', 'biwc', 'fz', 'jd', 'ajijhy']
outputs = ['jxv', 'biwuc', 'fdeki', 'jd', 'aaekjhy']

for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos = j
                break
        if diff_pos == -1:
            if len(inp) != len(out):
                diff_pos = min_len
        print(f"  Difference at position {diff_pos}")
        if diff_pos >= 0:
            print(f"  Before: '{inp[diff_pos:]}'")
            print(f"  After:  '{out[diff_pos:]}'")
    print()

